      <ConfirmDialog :show="!!pending" :title="t('channelOps.confirmTitle')" :message="confirmationMessage" :confirm-text="t('channelOps.confirm')" :danger="true" @cancel="!busy && (pending = null)" @confirm="confirmPending" />
    </div>
